class FO:
    def __init__(s,name,arg=None): s.name=name; s.arg=arg
    def get_name(s): return s.name
    def get_arg(s): return s.arg
class Inv:
    def __init__(s,fol,ops): s.flag_option_list=fol; s.operand_list=ops
class Base:
    def __init__(s,inv): s.cmd_inv=inv; s.calls=[]; s.parallelizers=[]; s.commutative=False
    def does_flag_option_list_contain_at_least_one_of(s,names): return any(f.name in names for f in s.cmd_inv.flag_option_list)
    def get_flag_option_list_filtered_with(s,names): return [f for f in s.cmd_inv.flag_option_list if f.name in names]
    def get_operand_list_length(s): return len(s.cmd_inv.operand_list)
    def __getattr__(s,n):
        if n.startswith(('set_','all_','if_','only_','append_to_parallelizer_list')):
            def rec(*a,**k):
                if n=='append_to_parallelizer_list': s.parallelizers.append(a[0])
                elif n=='set_commutative': s.commutative=True
                else: s.calls.append(n)
            return rec
        raise AttributeError(n)
EOF
