import sys, types, importlib, subprocess, random, os, shlex
sys.path.insert(0,'/tmp/sortcheck'); sys.modules['pash_annotations']=importlib.import_module('pa')
for sub in ['annotation_generation','annotation_generation.annotation_generators','annotation_generation.annotation_generators.InputOutputInfoGenerator_Interface','annotation_generation.annotation_generators.ParallelizabilityInfoGenerator_Interface','annotation_generation.datatypes','annotation_generation.datatypes.parallelizability','annotation_generation.datatypes.parallelizability.Parallelizer','annotation_generation.datatypes.parallelizability.AggregatorSpec']:
    sys.modules['pash_annotations.'+sub]=importlib.import_module('pa.'+sub)
sys.path.insert(0,'/home/tirandagan.guest/naive-arm/output/pash')
from pa.annotation_generation.annotation_generators._base import FO, Inv
from InputOutputInfoGeneratorSort import InputOutputInfoGeneratorSort as IO
from ParallelizabilityInfoGeneratorSort import ParallelizabilityInfoGeneratorSort as PAR
def inv(*fos, ops=()):
    return Inv([FO(f) if isinstance(f,str) else FO(*f) for f in fos], list(ops))
print("=== IO")
for name,i in [("no args",inv()),("one file",inv(ops=['a'])),("two files",inv(ops=['a','b'])),("-o",inv(('-o','x'),ops=['a'])),
               ("-c",inv('-c',ops=['a'])),("--check=quiet stdin",inv(('--check','quiet'))),("files0",inv(('--files0-from','-'))),("-n -k",inv('-n',('-k','2'),ops=['a']))]:
    g=IO(i); g.generate_info(); print(f"{name:22} ->", g.calls)
print("=== PAR")
for name,i in [("plain",inv()),("-n -r",inv('-n','-r',ops=['a'])),("-k2,2n -t:",inv(('-k','2,2n'),('-t',':'))),("-u",inv('-u')),("-s -k1,1",inv('-s',('-k','1,1'))),
               ("-c",inv('-c')),("-m",inv('-m')),("-R",inv('-R')),("--sort=random",inv(('--sort','random'))),("--sort=numeric",inv(('--sort','numeric'))),
               ("-o",inv(('-o','x'))),("-z",inv('-z')),("--debug",inv('--debug')),("files0",inv(('--files0-from','l'))),("-S 1M --parallel 4 -n",inv(('-S','1M'),('--parallel','4'),'-n'))]:
    g=PAR(i); g.generate_info(); print(f"{name:22} ->", [(p[0],p[1][0]) for p in g.parallelizers], "commutative" if g.commutative else "")
print("=== end-to-end: split -> seq mapper -> merge aggregator == sequential")
random.seed(1); S='/usr/bin/sort'
lines=[f"{random.choice('abcABC')}{random.randint(0,30)}:{random.choice(['x','y','z','X'])} {random.randint(1,5)}K {random.choice(['Jan','feb','MAR','1.10','1.9'])}\n" for _ in range(600)]
open('/tmp/sortcheck/in.txt','w').write(''.join(lines))
def run(cmd, infile=None, extra=()):
    return subprocess.run(cmd+list(extra), stdin=open(infile) if infile else None, capture_output=True, text=True).stdout
def split(mode,k):
    if mode=='CC': n=(len(lines)+k-1)//k; return [lines[i*n:(i+1)*n] for i in range(k)]
    return [lines[i::k] for i in range(k)]
fails=0
for opt_sets in [[], ['-n'], ['-r'], ['-f'], ['-b','-d'], ['-g'], ['-h','-k','2,2'], ['-V','-k','3,3'], ['-M','-k','3,3'], ['-i','-r'], ['-t',':','-k','2,2','-r'], ['-k','2,2n','-k','1,1r'],
                 ['-u'], ['-u','-k','1,1'], ['-s','-k','1,1'], ['-s','-f'], ['--sort=numeric'], ['-S','1M','--parallel','2','-n'], ['-f','-u'], ['-k','1.2,1n']]:
    fos=[]; it=iter(opt_sets)
    for w in it:
        if w in ('-k','-t','-S','--parallel'): fos.append(FO(w,next(it)))
        elif w.startswith('--sort='): fos.append(FO('--sort',w.split('=')[1]))
        else: fos.append(FO(w))
    g=PAR(Inv(fos,[])); g.generate_info()
    seq=run([S]+opt_sets,'/tmp/sortcheck/in.txt')
    for ptype,(agg,_) in g.parallelizers:
        for k in (2,3,5):
            parts=[]
            for j,chunk in enumerate(split(ptype,k)):
                fn=f'/tmp/sortcheck/part{j}'; open(fn,'w').write(''.join(chunk)); parts.append(fn)
                open(fn+'.s','w').write(run([S]+opt_sets,fn))
            # 2-ary aggregator folded left over parts
            acc=parts[0]+'.s'
            for j in range(1,k):
                out=f'/tmp/sortcheck/acc{j}'; open(out,'w').write(run(shlex.split(agg),None,[acc,parts[j]+'.s'])); acc=out
            if g.commutative:  # also try reversed order
                accr=parts[-1]+'.s'
                for j in range(k-2,-1,-1):
                    out=f'/tmp/sortcheck/accr{j}'; open(out,'w').write(run(shlex.split(agg),None,[accr,parts[j]+'.s'])); accr=out
                if open(accr).read()!=seq: print("FAIL reversed-order merge",opt_sets,ptype,k); fails+=1
            if open(acc).read()!=seq: print("FAIL",opt_sets,ptype,k,agg); fails+=1
    print(f"{' '.join(opt_sets) or '(none)':34} parallelizers={[p[0] for p in g.parallelizers]} agg={g.parallelizers[0][1][0] if g.parallelizers else None}")
print("end-to-end failures:",fails)
EOF
python3 -I test_gen.py

